CREATE TABLE "epi_comunicacao_titular" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY (sequence name "epi_comunicacao_titular_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"registro_id" bigint NOT NULL,
	"servidor_id" integer NOT NULL,
	"tipo" varchar(24) NOT NULL,
	"observacao" text,
	"criado_por" integer NOT NULL,
	"criado_em" timestamp with time zone NOT NULL,
	"retirada_em" timestamp with time zone,
	"retirada_por" integer,
	"tratada_em" timestamp with time zone,
	"tratada_por" integer,
	"tratamento" text,
	"requisicao_id" integer,
	CONSTRAINT "pk_epi_comunicacao_titular" PRIMARY KEY("id"),
	CONSTRAINT "ck_comunicacao_tipo" CHECK (tipo IN ('EXTRAVIADO','DESGASTE','TEMPO_DE_USO','PERDA_DE_EFICACIA','ALTERACAO_NO_TRABALHO')),
	CONSTRAINT "ck_comunicacao_retirada" CHECK ((retirada_em IS NULL) = (retirada_por IS NULL)),
	CONSTRAINT "ck_comunicacao_tratada" CHECK ((tratada_em IS NULL) = (tratada_por IS NULL)),
	CONSTRAINT "ck_comunicacao_desfecho" CHECK (retirada_em IS NULL OR tratada_em IS NULL)
);
--> statement-breakpoint
