ALTER TABLE "epi_requisicao_item" ADD COLUMN "motivo" varchar(16);--> statement-breakpoint
-- NUVEM (escrito à mão): os itens anteriores à 0015 recebem o motivo pela
-- finalidade do pedido (dominio/epi.ts, MOTIVO_ITEM_POR_FINALIDADE).
UPDATE "epi_requisicao_item" i SET "motivo" = CASE r."finalidade"
    WHEN 'PRIMEIRA_ENTREGA' THEN 'USO_INICIAL'
    WHEN 'DANO' THEN 'DANO'
    WHEN 'PERDA' THEN 'PERDA'
    ELSE 'DESGASTE'
  END
FROM "epi_requisicao" r
WHERE r."id" = i."requisicao_id" AND i."motivo" IS NULL;--> statement-breakpoint
